import { renderOrderService, renderAccountDownloads } from "../lib/order-service";
import type { OrderService, DownloadActivity } from "../../../src/lib/customer-service";
import { LANGUAGE_CODES, languageName } from "../../../src/lib/languages";
// Interface privée : toutes les données sont chargées après contrôle de la session.
type Language = {code:string|null;label:string;source:string;transactional_code?:string;confidence?:string};
type Client = { language:Language; id:number; email:string; display_name:string; company:string; stage:string; internal:boolean; created_at:number; last_order_at:number|null; last_login_at:number|null; paid_orders:number; revenue_cents:number; open_tasks:number };
type Task = { id:number; title:string; customer_id:number|null; due_on:string|null; done_at?:number|null; email?:string; display_name?:string };
type Count = {label:string;count:number};
type Overview = { checked_at:number; days:number; revenue:{orders:number;customers:number;revenue_cents:number}; all_time:{orders:number;customers:number;revenue_cents:number}; daily:{day:string;revenue_cents:number;orders:number}[]; traffic:{requests:number;average_ms:number;errors:number}; web:{pageviews:number;visitor_days:number;first_event:number|null}; coverage:{first_event:number|null}; customers:Client[]; tasks:Task[]; revision:string };
type SearchRow = {keys?:string[];clicks:number;impressions:number;ctr:number;position:number};
type Visibility = { available:boolean; reason?:string; checked_at?:number; start?:string; end?:string; total?:SearchRow; queries?:SearchRow[]; pages?:SearchRow[]; daily?:SearchRow[] };
type Dataset = {id:string;name:string;current_version:string;released_at:number|null;size_bytes:number|null};
type Check = {name:string;checked_at:number;encrypted:boolean;restore_check:string;size_bytes:number};
type Flow = {id:number;name:string;state:string;html_url:string};
type Run = {id:number;workflow_id:number;name:string;status:string;conclusion:string|null;created_at:string;html_url:string};
type Delivery = {id:number;order_id:number;dataset_id:string;state:string;attempts:number;next_attempt_at:number;last_error:string|null;sent_at:number|null};
type Financial = {charge_id:string;livemode:number;notification_pending:number;state:string;attempts:number;next_attempt_at:number;last_error:string|null;checked_at:number|null;order_id:number|null;order_status:string|null;refunded_chf:number|null;dispute_status:string|null};
type Operations = {financial?:Financial[];deliveries?:Delivery[];checked_at:number;datasets:Dataset[];checks:Check[];workflows:{available:boolean;items?:Flow[];runs?:Run[];checked_at?:number};revision:string};
type Mail = {language:Language;mailbox?:string;id:string;source:string;from:string;to:string[];subject:string;created_at:string;status:string;folder?:string};
type Mailbox = {checked_at:number;incoming:{available:boolean;accounts:{id:string;email:string;scope:string;available:boolean;reason?:string}[]};outgoing:{available:boolean;reason?:string;has_more?:boolean};items:Mail[]};
type Detail = {account_downloads?:DownloadActivity[];customer:Client;orders:{service?:OrderService;legal?:{status:string;url:string|null;terms_version?:string;locale?:string;event_created_at?:number};id:number;amount_chf:number;refunded_chf:number;dispute_status:string|null;financial_checked_at:number|null;items_json:string;status:string;created_at:number;stripe_payment_intent:string;stripe_session_id:string}[];entitlements:{dataset_id:string;updates_until:number|null;current_version:string}[];notes:{id:number;body:string;created_at:number}[];tasks:Task[]};
function legalOrder(order: Detail['orders'][number]): string {
  const l = order.legal;
  if (l?.status === 'accepted' && l.url && /^\/(?:de\/|en\/)?legal\/versions\/\d{4}-\d{2}-\d{2}\/cgv$/.test(l.url)) {
    return `<br/><small>CGV acceptées · <a href="${e(l.url)}" target="_blank" rel="noopener">${e(l.terms_version)} · ${e(l.locale?.toUpperCase())}</a> · ${date(l.event_created_at,true)}</small>`;
  }
  return `<br/><small>${l?.status === 'unverified' ? 'CGV : preuve à contrôler' : 'CGV : acceptation versionnée non collectée'}</small>`;
}
const $ = <T extends HTMLElement=HTMLElement>(id:string) => document.getElementById(id) as T;
const e = (v:unknown) => String(v ?? '').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]!));
const nf = new Intl.NumberFormat('fr-CH');
const num = (n:number|null|undefined) => n == null ? '—' : nf.format(n);
const money = (c:number) => new Intl.NumberFormat('fr-CH',{minimumFractionDigits:c%100?2:0,maximumFractionDigits:2}).format(c/100);
const date = (v:string|number|null|undefined, time=false) => v ? new Intl.DateTimeFormat('fr-CH',{timeZone:'Europe/Zurich',day:'2-digit',month:'short',year:time?undefined:'numeric',...(time?{hour:'2-digit',minute:'2-digit'}:{})}).format(new Date(v)) : 'Non enregistré';
const initials = (s:string) => e(s.replace(/@.*/,'').split(/[ ._-]/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase());
const stages:Record<string,string>={nouveau:'Nouveau',actif:'Actif',a_recontacter:'À recontacter',en_attente:'En attente',clos:'Clos'};
const states:Record<string,string>={delivered:'Livré',sent:'Envoyé',opened:'Ouverture signalée',clicked:'Clic signalé',bounced:'Rejeté',delivery_delayed:'Livraison retardée',complained:'Plainte',failed:'Échec',unread:'Non lu',seen:'Lu dans la boîte',queued:'En attente',scheduled:'Programmé'};
const sectionInfo:Record<string,[string,string,string]>={overview:['Vue d’ensemble','VOTRE ACTIVITÉ, EN CLAIR','Les chiffres utiles. Les prochaines actions. Le reste à portée de main.'],clients:['Clients','UNE RELATION, UNE VUE COMPLÈTE','Achats, accès, échanges et prochaines actions au même endroit.'],mail:['Messagerie','GARDER LE FIL','Les messages du projet et leur livraison, reliés à vos clients.'],audience:['Audience','COMPRENDRE LES VISITES','Séparer les visites estimées, les robots et l’usage des services.'],visibility:['Visibilité','ÊTRE TROUVÉ','Ce que Google montre et ce qui amène des visiteurs sur le site.'],data:['Données & qualité','LA CONFIANCE COMMENCE ICI','Les versions réellement disponibles et la fraîcheur des sources.'],operations:['Automatisations','SAVOIR CE QUI TOURNE','Derniers passages, réussites vérifiées et points à reprendre.']};
let active = sectionInfo[location.hash.slice(1)] ? location.hash.slice(1) : 'overview';
let overview:Overview; let visibility:Visibility={available:false}; let operations:Operations; let mailbox:Mailbox;
let mailAbort:AbortController|null=null, mailOpen=0;
let generation=0, filter='', showInternal=false, mailFilter='all', clientOpen:number|null=null;
const days=()=>Number($<HTMLSelectElement>('period').value);
class ApiError extends Error {constructor(public status:number,public code:string){super(code)}}
async function api<T>(path:string, method='GET', body?:unknown):Promise<T>{
 const r=await fetch('/api/admin/crm'+path,{method,credentials:'same-origin',cache:'no-store',headers:method==='GET'?{}:{'Content-Type':'application/json','x-osd-csrf':'dashboard'},...(body===undefined?{}:{body:JSON.stringify(body)})});
 if(!r.ok){if([401,403].includes(r.status)){ $<HTMLDialogElement>('detail').close();$('detail-body').textContent='';$('workspace').hidden=true;$('gate').hidden=false;$('gate-status').textContent='Votre session a expiré ou ce compte n’est pas autorisé.';$('login-form').hidden=false; }const j=await r.json().catch(()=>({error:'request_failed'}));throw new ApiError(r.status,j.error)}
 return r.json();
}
function toast(message:string){$('toast').textContent=message;$('toast').hidden=false;window.setTimeout(()=>$('toast').hidden=true,4500)}
function failure(message='Les données n’ont pas pu être actualisées. Réessayez.'){ $('notice').textContent=message;$('notice').hidden=false; }
const empty=(title:string,sub='')=>`<div class="empty"><div class="empty-icon" aria-hidden="true">○</div><strong>${e(title)}</strong><p>${e(sub)}</p></div>`;
const pill=(text:string,color='')=>`<span class="pill ${color}">${e(text)}</span>`;
const kpi=(label:string,value:string,unit:string,foot:string)=>`<div class="kpi"><div class="kpi-label">${e(label)}<span aria-hidden="true">↗</span></div><div class="kpi-value">${value}${unit?`<small>${e(unit)}</small>`:''}</div><p class="kpi-foot">${e(foot)}</p></div>`;
function orderItems(value:string){try{const rows=JSON.parse(value);return Array.isArray(rows)?rows.map(x=>typeof x==='string'?x:'Produit').join(', '):'Produit à vérifier'}catch{return 'Produit à vérifier'}}
const clientName=(c:Client)=>c.display_name||c.email.split('@')[0];
const languagePill=(l:Language)=>pill(l.code?`${l.code.toUpperCase()} · ${l.label}`:"Langue à confirmer",l.code?"blue":"amber");
const languageOptions=(selected:string|null,empty=true)=>(empty?`<option value="">À confirmer</option>`:"")+LANGUAGE_CODES.map(code=>`<option value="${code}" ${code===selected?"selected":""}>${e(languageName(code))} (${code.toUpperCase()})</option>`).join("");
const person=(c:Client)=>`<div class="person"><div class="person-icon">${initials(clientName(c))}</div><div><strong>${e(clientName(c))}</strong><small>${e(c.company||c.email)}</small><span class="client-language">${languagePill(c.language)}</span></div></div>`;
const noteSource=(text:string)=>`<p class="source-note">${e(text)}</p>`;
function clientTable(rows:Client[],short=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Suivi</th><th class="mobile-hide">Dernier achat</th><th>Total achats</th><th></th></tr></thead><tbody>${rows.slice(0,short?5:1000).map(c=>`<tr class="clickable"><td><button class="text-button" data-client="${c.id}">${person(c)}</button></td><td>${pill(c.internal?'Interne / test':stages[c.stage]||c.stage,c.internal?'':c.stage==='actif'?'green':c.stage==='a_recontacter'?'amber':'blue')}</td><td class="mobile-hide">${date(c.last_order_at)}</td><td class="number">${money(c.revenue_cents)} <span class="muted">CHF</span></td><td><button class="icon-button" data-client="${c.id}" aria-label="Ouvrir la fiche de ${e(clientName(c))}">↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('Aucun client dans cette sélection','Les comptes internes peuvent être affichés séparément.');}
function actions(tasks:Task[]){return tasks.length?tasks.map(t=>`<div class="action-row"><button class="action-check" data-done="${t.id}" aria-label="Terminer : ${e(t.title)}">${t.done_at?'✓':''}</button><div class="action-copy"><strong>${e(t.title)}</strong><p>${t.email?`${e(t.display_name||t.email)} · `:''}${t.due_on?`Pour le ${date(t.due_on)}`:'Sans échéance'}</p></div>${t.due_on&&t.due_on<new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Zurich'})?pill('À traiter','amber'):''}</div>`).join(''):empty('Une place pour vos prochaines actions','Ajoutez un suivi client ou une amélioration à ne pas oublier.');}
function taskForm(cid?:number){return `<form class="task-form" data-task-customer="${cid||''}"><input name="title" required maxlength="240" placeholder="Une prochaine action…" aria-label="Prochaine action"/><input name="due_on" type="date" aria-label="Date souhaitée"/><button class="button" type="submit">+ Ajouter</button></form>`;}
function revenueChart(){const points=[];for(let i=overview.days-1;i>=0;i--){const day=new Date(Date.now()-i*86400000).toISOString().slice(0,10);points.push({day,value:overview.daily.find(x=>x.day===day)?.revenue_cents||0})}const bucket=points.length>90?Math.ceil(points.length/60):1;const groups=[];for(let i=0;i<points.length;i+=bucket)groups.push({day:points[i].day,value:points.slice(i,i+bucket).reduce((s,p)=>s+p.value,0)});const max=Math.max(...groups.map(x=>x.value),1);return `<div class="chart" role="img" aria-label="Évolution des achats sur ${overview.days} jours : ${money(overview.revenue.revenue_cents)} francs"><span class="skip">${num(overview.revenue.orders)} commandes</span>${groups.map(x=>`<div class="bar-wrap" title="${date(x.day)} : ${money(x.value)} CHF"><div class="bar" style="height:${Math.max(.7,100*x.value/max)}%;opacity:${x.value?1:.15}"></div></div>`).join('')}</div><div class="chart-labels"><span>${date(points[0].day)}</span><span>Aujourd’hui</span></div><div class="chart-summary"><span><strong>${num(overview.revenue.orders)}</strong> commande${overview.revenue.orders!==1?'s':''}</span><span><strong>${num(overview.revenue.customers)}</strong> client${overview.revenue.customers!==1?'s':''} payant${overview.revenue.customers!==1?'s':''}</span></div>`;}
function dataHealth(){return operations.datasets.map(d=>{const age=d.released_at?(Date.now()-d.released_at)/86400000:Infinity;const okay=d.id==='finma'?age<3:d.id==='tares'?age<10:age<400;return `<div class="health-row"><div class="health-icon ${okay?'':'amber'}">${okay?'✓':'!'}</div><div class="health-copy"><strong>${e(d.id.toUpperCase())}</strong><p>Version ${e(d.current_version||'non publiée')}</p></div>${pill(okay?'Disponible':'À vérifier',okay?'green':'amber')}</div>`}).join('');}
function renderOverview(){const real=overview.customers.filter(c=>!c.internal&&c.paid_orders>0);const due=overview.tasks.length;return `<div class="hero"><div class="hero-mark">↗</div><div><h2>${due?`${due} action${due>1?'s':''} pour faire avancer le projet`:'Votre activité, sans perdre le fil.'}</h2><p>${real.length?`${num(real.length)} client${real.length>1?'s':''} payant${real.length>1?'s':''} au total. Retrouvez chaque achat, chaque échange et chaque prochaine étape.`:'Les achats et les suivis clients apparaîtront ici dès leur enregistrement.'}</p></div><a class="button" href="#clients">Ouvrir le CRM <span>→</span></a></div><div class="kpis">${kpi('Ventes sur la période',money(overview.revenue.revenue_cents),'CHF','Commandes payées · hors comptes internes')}${kpi('Clients payants',num(overview.revenue.customers),'',`${num(overview.all_time.customers)} au total depuis le lancement`)}${kpi('Clics depuis Google',visibility.available?num(visibility.total?.clicks):'—','','Search Console · données finales à J−3')}${kpi('Prochaines actions',num(due),'',due?'Vos suivis à traiter':'Ajoutez votre première action')}</div><div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>Les ventes, simplement</h2><p>Achats payés, hors comptes internes et mode test</p></div>${pill('CHF','green')}</div>${revenueChart()}${noteSource('Source : commandes de l’application. Remboursements confirmés déduits ; contestations ouvertes ou perdues exclues. Montants avant frais Stripe, rattachés à la date d’achat : ce chiffre ne représente pas les versements bancaires.')}</section><section class="panel"><div class="panel-heading"><div><h2>À faire avancer</h2><p>Des actions concrètes, à votre rythme</p></div>${pill(String(due))}</div>${actions(overview.tasks.slice(0,5))}${taskForm()}</section></div><div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>Vos clients</h2><p>Les relations qui font grandir OpenSwissData</p></div><a class="subtle-link" href="#clients">Tous les clients →</a></div>${clientTable(real,true)}</section><section class="panel"><div class="panel-heading"><div><h2>La qualité du service</h2><p>Les versions réellement distribuées</p></div><a class="subtle-link" href="#data">Détail →</a></div>${dataHealth()}</section></div>`;}
function renderClients(){const rows=overview.customers.filter(c=>(showInternal||!c.internal)&&[c.email,c.display_name,c.company,stages[c.stage]].join(' ').toLowerCase().includes(filter.toLowerCase()));return `<div class="toolbar"><input id="client-search" class="search" type="search" placeholder="Chercher un nom, une entreprise, un mail…" aria-label="Rechercher un client" value="${e(filter)}"/><label class="toggle"><input id="show-internal" type="checkbox" ${showInternal?'checked':''}/> Inclure les comptes internes / tests</label></div><section class="panel"><div class="panel-heading"><h2>${rows.length} fiche${rows.length>1?'s':''} client${rows.length>1?'s':''}</h2>${pill('Suivi privé')}</div><div id="client-results">${clientTable(rows)}</div></section><section class="panel" style="margin-top:24px"><div class="panel-heading"><h2>Vos prochaines actions</h2></div>${actions(overview.tasks)}${taskForm()}</section>`;}
function metricList(rows:Count[],limit=12){const max=Math.max(1,...rows.map(r=>r.count));return rows.length?rows.slice(0,limit).map(r=>`<div class="metric-row"><span>${e(r.label==='inconnu'?'Non renseigné':r.label)}</span><strong>${num(r.count)}</strong></div><div class="metric-track"><i style="width:${100*r.count/max}%"></i></div>`).join(''):empty('Pas encore de données sur cette période');}
function trend(points:{day:string;value:number}[],label:string){if(!points.length)return empty('Aucune mesure disponible');const max=Math.max(1,...points.map(p=>p.value));const coords=points.map((p,i)=>`${points.length===1?300:8+i*584/(points.length-1)},${135-p.value/max*115}`).join(' ');return `<svg class="spark" viewBox="0 0 600 160" role="img" aria-label="${e(label)}"><path d="M0 135H600 M0 77H600 M0 20H600" stroke="#edf0ef" fill="none"/><polyline points="${coords}" stroke="#47846b" stroke-width="2.5" fill="none" vector-effect="non-scaling-stroke"/>${points.length===1?`<circle cx="300" cy="${135-points[0].value/max*115}" r="4" fill="#47846b"/>`:''}</svg><div class="chart-labels"><span>${date(points[0].day)}</span><span>${date(points.at(-1)!.day)}</span></div>`;}
async function renderAudience(){const a=await api<{daily:{day:string;views:number;visitors:number}[];pages:Count[];sources:Count[];countries:Count[];split:Count[];api:Count[];actions:Count[]}>('/audience?days='+days());return `<div class="notice">La mesure des pages commence ${overview.coverage.first_event?`le ${date(overview.coverage.first_event)}`:'avec ce dashboard'}. Les visites antérieures ne sont pas reconstituées à partir des appels API. Les visiteurs sont estimés et recomptés chaque jour.</div><div class="kpis">${kpi('Pages consultées',num(overview.web.pageviews),'','Navigateurs identifiés · robots connus exclus')}${kpi('Visiteurs-jours estimés',num(overview.web.visitor_days),'','Une même personne peut compter sur plusieurs jours')}${kpi('Appels API',num(overview.traffic.requests),'','Inclut outils, robots et clients techniques')}${kpi('Erreurs serveur',num(overview.traffic.errors),'',`Temps moyen API : ${num(overview.traffic.average_ms)} ms`)}</div><section class="panel" style="margin-bottom:24px"><div class="panel-heading"><h2>La fréquentation au fil des jours</h2>${pill('Visiteurs estimés')}</div>${trend(a.daily.map(x=>({day:x.day,value:x.visitors})),'Visiteurs quotidiens estimés')}${noteSource('La catégorie du navigateur ne prouve pas à elle seule une présence humaine. Les accès au bureau et à l’espace client sont exclus.')}</section><div class="grid-equal"><section class="panel"><div class="panel-heading"><h2>Pages consultées</h2></div>${metricList(a.pages)}</section><section class="panel"><div class="panel-heading"><h2>Provenance déclarée</h2></div>${metricList(a.sources)}${noteSource('Absence de source : accès direct, navigation interne ou référent non transmis. Ne permet pas d’attribuer une vente.')}</section><section class="panel"><div class="panel-heading"><h2>Qui appelle les services ?</h2></div>${metricList(a.api.map(x=>({...x,label:({desktop:'Navigateur ordinateur présumé',mobile:'Navigateur mobile présumé',bot:'Robots connus',automation:'Outils automatisés',other:'Non classé'} as Record<string,string>)[x.label]||x.label})))}</section><section class="panel"><div class="panel-heading"><h2>Actions enregistrées</h2></div>${metricList(a.actions)}</section></div>`;}
function renderVisibility(){if(!visibility.available)return `<section class="panel">${empty('Search Console momentanément indisponible',visibility.reason||'La connexion doit être vérifiée.')}<div class="source-links"><a href="https://search.google.com/search-console?resource_id=sc-domain%3Aopenswissdata.com" target="_blank" rel="noopener">Ouvrir Search Console ↗</a></div></section>`;const t=visibility.total!;const table=(rows:SearchRow[],kind:string)=>rows.length?`<div class="table-wrap"><table><thead><tr><th>${kind}</th><th>Clics</th><th>Impressions</th><th>Position</th></tr></thead><tbody>${rows.map(r=>`<tr><td style="max-width:380px;overflow-wrap:anywhere">${e(kind==='Page'?(r.keys?.[0]||'').replace('https://www.openswissdata.com',''):r.keys?.[0])}</td><td>${num(r.clicks)}</td><td>${num(r.impressions)}</td><td>${r.position.toFixed(1)}</td></tr>`).join('')}</tbody></table></div>`:empty('Aucune ligne disponible');return `<div class="status-line">${pill('Google Search Console connecté','green')}<span class="fine">Du ${date(visibility.start)} au ${date(visibility.end)} · données finales</span></div><div class="kpis">${kpi('Clics Google',num(t.clicks),'','Visites issues des résultats de recherche')}${kpi('Impressions',num(t.impressions),'','Apparitions dans les résultats de recherche')}${kpi('Taux de clic',(t.ctr*100).toFixed(2),'%','Clics divisés par impressions')}${kpi('Position moyenne',t.impressions?t.position.toFixed(1):'—','','Toutes les recherches sur la période')}</div><section class="panel" style="margin-bottom:24px"><div class="panel-heading"><h2>Les clics au fil des jours</h2><a class="subtle-link" href="https://search.google.com/search-console?resource_id=sc-domain%3Aopenswissdata.com" target="_blank" rel="noopener">Ouvrir Google ↗</a></div>${trend((visibility.daily||[]).map(r=>({day:r.keys![0],value:r.clicks})),'Clics Google quotidiens')}</section><div class="grid-equal"><section class="panel"><div class="panel-heading"><h2>Ce que les gens recherchent</h2></div>${table(visibility.queries||[],'Recherche')}${noteSource('Google masque certaines recherches rares. La somme des lignes peut être inférieure au total.')}</section><section class="panel"><div class="panel-heading"><h2>Les pages qui attirent</h2></div>${table(visibility.pages||[],'Page')}</section></div>${noteSource('Source : propriété Google Search Console openswissdata.com. Les données ne mesurent ni les achats ni les visites provenant d’autres moteurs. Le délai de trois jours évite les résultats encore partiels.')}`;}
function renderData(){return `<div class="quality-grid">${operations.datasets.map(d=>{const age=d.released_at?Math.floor((Date.now()-d.released_at)/86400000):null;const stale=age===null||(d.id==='finma'?age>3:d.id==='tares'?age>10:age>400);return `<section class="data-card">${pill(d.id.toUpperCase(),stale?'amber':'green')}<h2>${e(d.name)}</h2><p class="fine">Dernière version publiée</p><div class="data-version">${e(d.current_version||'—')}</div><p class="fine">${date(d.released_at)}${age!==null?` · il y a ${age} jour${age>1?'s':''}`:''}</p><div class="metric-row"><span>Archive</span><strong>${d.size_bytes?(d.size_bytes/1e6).toFixed(2)+' Mo':'—'}</strong></div><p class="source-note">${d.id==='finma'?'Collecte quotidienne. Les champs non fournis par la source restent vides.':d.id==='tares'?'Collecte à revalider avant réactivation.':'Vérifier les millésimes officiels avant toute actualisation.'}</p><div class="source-links"><a href="/datasets/${encodeURIComponent(d.id)}?v=${encodeURIComponent(overview.revision.slice(0,7))}" target="_blank" rel="noopener">Voir la fiche ↗</a>${d.id==='finma'?'<a href="/api/catalog/finma?format=csv">Échantillon CSV ↓</a>':''}</div></section>`}).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-heading"><h2>Lire les données avec justesse</h2></div><div class="grid-equal" style="margin-bottom:0"><div><h3>Une ligne n’est pas toujours une entreprise</h3><p class="fine" style="margin-top:8px">Le registre FINMA peut contenir plusieurs autorisations pour un même UID. Les avertissements sont fournis séparément. Une ressemblance de nom ne constitue pas une identité.</p></div><div><h3>L’historique montre ce qui a été observé</h3><p class="fine" style="margin-top:8px">Les jours sans collecte sont indiqués dans l’archive. Une date d’observation ne remplace pas une date de décision de l’autorité.</p></div></div></section>`;}
function flowName(s:string){return s.includes('backup')||s.includes('SQLite')?'Sauvegarde et restauration':s.includes('FINMA')?'Collecte FINMA quotidienne':s.includes('TARES')?'Collecte TARES':s.includes('canary')?'Surveillance des sources':s.includes('Cleanup')?'Nettoyage des données expirées':s==='CI'?'Vérifications avant publication':s;}
function renderDeliveries(){
  const rows=operations.deliveries||[];
  const labels:Record<string,string>={pending:'À reprendre',processing:'En cours',sent:'Remis au service mail',review:'Vérification nécessaire',cancelled:'Annulée'};
  const reasons:Record<string,string>={version_unavailable:'Le fichier attendu n’est pas encore disponible.',delivery_confirmation_required:'Vérifier la réception chez le service mail avant tout nouvel envoi.',no_api_key:'Le service mail doit être configuré.',resend_error:'Le service mail n’a pas confirmé l’envoi.',delivery_error:'Un incident a interrompu la tentative.',order_not_paid:'La commande ne donne plus droit à cette livraison.',financial_access_suspended:'Livraison suspendue à la suite d’un remboursement ou d’une contestation.',financial_sync_pending:'Vérification du paiement en attente chez Stripe.'};
  return `<section class="panel" style="margin-bottom:24px"><div class="panel-heading"><div><h2>Livraisons des achats</h2><p>Suivi des nouvelles commandes · reprise automatique chaque minute</p></div>${pill(rows.some(x=>x.state==='review')?'À contrôler':rows.some(x=>x.state==='pending')?'Reprises prévues':'Suivi actif',rows.some(x=>x.state==='review')?'amber':'green')}</div>${rows.length?rows.map(d=>`<div class="flow-row"><div><strong>Commande ${num(d.order_id)} · ${e(d.dataset_id.toUpperCase())}</strong><p>${e(reasons[d.last_error||'']||'')}${d.state==='pending'?` Prochaine tentative : ${date(d.next_attempt_at,true)}.`:d.sent_at?` Remise le ${date(d.sent_at,true)}.`:''}</p></div>${pill(labels[d.state]||d.state,d.state==='sent'?'green':'amber')}</div>`).join(''):empty('Aucune nouvelle livraison enregistrée','Les achats antérieurs à ce suivi restent dans les fiches clients. Ils ne sont pas renvoyés automatiquement.')}${noteSource('« Remis au service mail » confirme l’acceptation du message. Sa réception effective se consulte dans la messagerie. Les 100 dernières livraisons sont affichées, avec les reprises en priorité.')}</section>`;
}
function orderStatus(status:string,refunded=0){return ({paid:refunded?'Partiellement remboursée · accès conservés':'Payée',refunded:'Remboursée · accès retirés',disputed:'Contestée · accès suspendus',dispute_lost:'Contestation perdue · accès retirés',financial_pending:'Paiement en cours de vérification'} as Record<string,string>)[status]||status}
function disputeLabel(status:string){return ({needs_response:'Réponse à préparer dans Stripe',under_review:'Contestation en cours d’examen',lost:'Contestation perdue',won:'Contestation gagnée',prevented:'Contestation évitée',warning_needs_response:'Demande d’information à traiter',warning_under_review:'Demande d’information en examen',warning_closed:'Demande d’information close'} as Record<string,string>)[status]||status}
function renderFinancial(){
 const rows=operations.financial||[];
 const reasons:Record<string,string>={financial_permission_denied:'L’accès Stripe aux paiements, remboursements ou contestations est refusé. Vérifier les droits de la clé.',financial_storage_full:'L’espace chiffré réservé au suivi financier ou le disque est plein. Une intervention est nécessaire.',financial_order_mismatch:'Le montant ou le mode Stripe ne correspond pas à la commande. Vérifier le paiement avant toute modification des droits.',financial_manual_order_status:'Cette commande porte un état manuel. Vérifier son traitement dans Stripe.',financial_format_changed:'La réponse Stripe a changé de format. Le traitement demande une adaptation.',financial_pagination_limit:'Le paiement dépasse la limite de lecture automatique. Vérification manuelle nécessaire.',financial_amount_invalid:'Les montants reçus sont incohérents. Aucun droit n’est recalculé.',financial_charge_mismatch:'La référence du paiement ne correspond pas à la notification. Vérification nécessaire.',financial_key_missing:'La clé Stripe de lecture doit être configurée.',financial_sync_failed:'Stripe ou le stockage est momentanément indisponible. La reprise reste programmée.'};
 return `<section class="panel" style="margin-bottom:24px"><div class="panel-heading"><div><h2>Remboursements et contestations</h2><p>État relu chez Stripe · les autres achats du client gardent leurs droits</p></div>${pill(rows.some(r=>r.state!=='synced')?'Vérifications à reprendre':'Suivi actif',rows.some(r=>r.state!=='synced')?'amber':'green')}</div>${rows.length?rows.map(r=>`<div class="flow-row"><div><strong>${r.order_id?`Commande ${num(r.order_id)}`:'Paiement sans commande de fichiers associée'}</strong><p>${r.state==='synced'?e(r.order_status?orderStatus(r.order_status,r.refunded_chf||0):'État conservé pour rapprochement avec une commande future.'):(r.notification_pending?'Notification en attente. ':'Relecture de contrôle en attente. ')+ 'Prochaine tentative : '+date(r.next_attempt_at,true)+'.'}${r.dispute_status?`<br/>${e(disputeLabel(r.dispute_status))}`:''}${r.refunded_chf?`<br/>Remboursé : ${money(r.refunded_chf)} CHF.`:''}${r.last_error?`<br/>${e(reasons[r.last_error]||'La lecture a échoué. Vérifier le paiement dans Stripe.')} · ${num(r.attempts)} tentative(s).`:''}</p><a href="https://dashboard.stripe.com/${r.livemode?'':'test/'}payments/${encodeURIComponent(r.charge_id)}" target="_blank" rel="noopener">Consulter dans Stripe ↗</a></div>${pill(r.state==='synced'?'Vérifié':'À reprendre',r.state==='synced'?'green':'amber')}</div>`).join(''):empty('Aucun événement financier enregistré','Les prochains remboursements et contestations apparaîtront ici. Ce suivi ne déclenche aucun remboursement.')}${noteSource('Achats de fichiers uniquement. Les notifications sont reprises chaque minute ; les paiements suivis sont relus toutes les six heures. Un remboursement partiel conserve les accès et demande un examen commercial dans Stripe. Une demande d’information bancaire seule ne suspend pas l’accès.')}</section>`;
}
function renderOperations(){const b=operations.checks.find(x=>x.name==='backup');const healthy=b&&b.encrypted&&b.restore_check==='ok'&&Date.now()-b.checked_at<60*3600000;return `${renderFinancial()}${renderDeliveries()}<div class="hero"><div class="hero-mark">${healthy?'✓':'!'}</div><div><h2>${healthy?'La sauvegarde a été restaurée avec succès.':'La sauvegarde demande une vérification.'}</h2><p>${b?`Dernier contrôle : ${date(b.checked_at,true)} · ${(b.size_bytes/1e6).toFixed(1)} Mo chiffrés.`:'Aucun témoin de restauration disponible.'}</p></div>${pill(healthy?'Vérifiée':'À vérifier',healthy?'green':'amber')}</div><div class="grid-two"><section class="panel"><div class="panel-heading"><div><h2>Les tâches automatiques</h2><p>État lu directement dans GitHub</p></div></div>${operations.workflows.available?(operations.workflows.items||[]).map(f=>{const run=operations.workflows.runs?.find(r=>r.workflow_id===f.id);return `<div class="flow-row"><div><strong>${e(flowName(f.name))}</strong><p>${run?`Dernier passage : ${date(run.created_at,true)} · ${run.conclusion==='success'?'réussi':run.status==='in_progress'?'en cours':e(run.conclusion||run.status)}`:'Aucun passage dans les 30 dernières exécutions consultées.'}</p><a href="${e(f.html_url)}" target="_blank" rel="noopener">Voir les exécutions ↗</a></div>${pill(f.state==='active'?'Active':'Suspendue',f.state==='active'?'green':'amber')}</div>`}).join(''):empty('GitHub momentanément indisponible','Aucun état actif n’est déduit sans vérification.')}</section><section class="panel"><div class="panel-heading"><h2>Repères d’exploitation</h2></div><div class="health-row"><div class="health-icon">↻</div><div class="health-copy"><strong>FINMA</strong><p>Collecte quotidienne à 06 h 17 en été, 05 h 17 en hiver (heure suisse). Alerte de fraîcheur après 72 heures.</p></div></div><div class="health-row"><div class="health-icon">▤</div><div class="health-copy"><strong>Sauvegarde</strong><p>Prévue à 05 h 15 en été, 04 h 15 en hiver (heure suisse). Déchiffrement et ouverture SQLite contrôlés avant validation.</p></div></div><div class="health-row"><div class="health-icon">⌁</div><div class="health-copy"><strong>Version de l’application</strong><p>${e(operations.revision.slice(0,7))} · révision servie par Railway</p></div></div><div class="health-row"><div class="health-icon amber">!</div><div class="health-copy"><strong>Surveillance indépendante</strong><p>Le contrôle horaire local dépend encore du Mac allumé. Sa relève sur Mac mini reste prévue.</p></div></div>${noteSource('Les horaires planifiés ne sont pas une garantie de passage à la minute. Les résultats ci-contre montrent les exécutions réellement enregistrées.')}</section></div>`;}
function renderMail(){const rows=mailbox.items.filter(m=>(mailFilter==='all'||(mailFilter==='sent'?m.source==='resend':m.source==='imap'))&&[m.subject,m.from,...m.to].join(' ').toLowerCase().includes(filter.toLowerCase()));return `<div class="status-line">${pill(mailbox.outgoing.available?'Envois connectés':'Envois indisponibles',mailbox.outgoing.available?'green':'amber')}${pill(`${mailbox.incoming.accounts.filter(a=>a.available).length} boîte(s) connectée(s) sur ${mailbox.incoming.accounts.length}`,mailbox.incoming.available?'green':'amber')}<a class="fine" href="https://ksuite.infomaniak.com/mail" target="_blank" rel="noopener">Ouvrir Infomaniak ↗</a></div>${mailbox.incoming.accounts.map(a=>a.available?`<div class="status-line">${pill(a.email,'green')}<span class="fine">${e(a.scope)}</span><button data-disconnect-mail="${e(a.email)}" class="text-button">Déconnecter</button></div>`:`<section class="connect-panel"><h3>${e(a.email)}</h3><p>${a.id==='cam_project'?'Seuls les messages qui mentionnent OpenSwissData dans leur objet ou leur texte, ou échangent avec @openswissdata.com, sont consultés. Le reste de votre boîte personnelle reste hors du CRM.':'Retrouvez les messages reçus, envoyés et les spams de la boîte de support.'}</p><details><summary class="fine" style="cursor:pointer">Connecter cette boîte Infomaniak</summary><form data-mail-connect style="margin-top:16px"><label class="field">Adresse<input name="user" type="email" value="${e(a.email)}" readonly/></label><label class="field">Mot de passe d’appareil Infomaniak<input name="pass" type="password" autocomplete="off" required maxlength="500"/></label>${a.id==='cam_project'?'<p class="notice">Ce mot de passe donne techniquement accès à toute la boîte. Le CRM filtre ses lectures, mais un accès au serveur pourrait exposer cet identifiant. Un message retenu apparaît en entier, y compris son historique cité.</p><label class="toggle"><input name="personal_scope_ack" type="checkbox" required/> J’autorise la connexion de cette boîte personnelle pour les messages OpenSwissData.</label>':''}<p class="fine">Créez un mot de passe d’appareil dédié, révocable chez Infomaniak. Il est conservé chiffré sur le serveur OpenSwissData (Railway) et dans les sauvegardes chiffrées du projet. Les copies temporaires de messages de plus de 30 jours sont effacées lors de la prochaine consultation, et celles de cette boîte à sa déconnexion. Les originaux restent dans la messagerie.</p><button class="primary" type="submit">Connecter et vérifier</button></form></details></section>`).join('')}<div class="toolbar"><div class="tabs"><button data-mail-filter="all" class="${mailFilter==='all'?'active':''}">Tous</button><button data-mail-filter="received" class="${mailFilter==='received'?'active':''}">Boîte Infomaniak</button><button data-mail-filter="sent" class="${mailFilter==='sent'?'active':''}">Envoyés</button></div><input id="mail-search" class="search" type="search" placeholder="Chercher un client, un objet, une adresse…" aria-label="Rechercher un mail" value="${e(filter)}"/></div><section class="panel" id="mail-results">${rows.length?rows.map(m=>`<button class="mail-item" data-mail-source="${e(m.source)}" data-mail-id="${e(m.id)}"><span class="mail-icon">${m.source==='resend'?'↗':'↙'}</span><div><div class="mail-meta">${e(m.source==='resend'?m.to.join(', '):m.from)}${m.mailbox?` · ${e(m.mailbox)}`:''}${m.folder?` · ${e(m.folder)}`:''}</div><div class="mail-title">${e(m.subject)}</div>${pill(states[m.status]||m.status,['delivered','seen'].includes(m.status)?'green':['failed','bounced'].includes(m.status)?'red':'')} ${m.language.code?pill(`Objet : ${m.language.label} présumé`,'blue'):''}</div><time>${date(m.created_at,true)}</time></button>`).join(''):empty('Aucun message dans cette sélection',mailFilter==='received'&&!mailbox.incoming.available?'Connectez la boîte pour consulter les messages reçus.':'Essayez un autre filtre.')}</section>${noteSource('Envois : jusqu’aux 100 derniers messages accessibles chez Resend. Réception : 90 derniers jours, jusqu’à 50 messages par dossier. Un statut livré ne prouve pas la lecture ; une ouverture signalée peut venir d’un filtre de messagerie.')}`;}
async function load(){const gen=++generation;$('notice').hidden=true;$<HTMLButtonElement>('refresh').disabled=true;try{const [o,op,v]=await Promise.all([api<Overview>('/overview?days='+days()),api<Operations>('/operations'),api<Visibility>('/visibility?days='+days())]);if(gen!==generation)return;overview=o;operations=op;visibility=v;$('gate').hidden=true;$('workspace').hidden=false;$('badge-clients').textContent=String(o.all_time.customers||'');$('freshness').textContent=`Actualisé le ${date(o.checked_at,true)} · version ${o.revision.slice(0,7)}`;await render();}catch(err){if(err instanceof ApiError&&[401,403,503].includes(err.status)){$('gate-status').textContent=err.status===503?'L’accès administrateur doit être activé.':'Connectez-vous pour retrouver vos clients et votre activité.';$('login-form').hidden=false;$('workspace').hidden=true;$('gate').hidden=false;}else{failure();$('gate-status').textContent='Le service ne répond pas pour le moment. Réessayez en actualisant.'}}finally{$<HTMLButtonElement>('refresh').disabled=false;}}
async function render(){if(!overview)return;const gen=++generation;const [title,kicker,description]=sectionInfo[active];$('period-control').hidden=!['overview','audience','visibility'].includes(active);$('section-label').textContent=title;$('page-title').textContent=title;$('page-kicker').textContent=kicker;$('page-description').textContent=description;document.querySelectorAll('[data-nav]').forEach(a=>a.getAttribute('data-nav')===active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));let html='';try{if(active==='overview')html=renderOverview();if(active==='clients')html=renderClients();if(active==='visibility')html=renderVisibility();if(active==='data')html=renderData();if(active==='operations')html=renderOperations();if(active==='audience'){$('view').innerHTML='<div class="loading-panel"><div class="spinner"></div>Lecture de la fréquentation…</div>';html=await renderAudience()}if(active==='mail'){$('view').innerHTML='<div class="loading-panel"><div class="spinner"></div>Lecture des messages…</div>';mailbox=await api<Mailbox>('/mail');html=renderMail()}if(gen!==generation)return;$('view').innerHTML=html;bind();}catch{failure('Cette source est momentanément indisponible. Vous pouvez continuer dans les autres espaces.');$('view').innerHTML=empty('Chargement interrompu','Utilisez Actualiser pour réessayer.')}}
function bind(){document.querySelectorAll<HTMLButtonElement>('[data-client]').forEach(b=>b.onclick=()=>openClient(Number(b.dataset.client)));document.querySelectorAll<HTMLButtonElement>('[data-done]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/tasks/'+b.dataset.done,'PATCH',{done:true});toast('Action terminée');if(clientOpen)await openClient(clientOpen);await load()}catch{toast('L’action n’a pas été enregistrée. Réessayez.')}finally{b.disabled=false}});document.querySelectorAll<HTMLFormElement>('.task-form').forEach(f=>f.onsubmit=async ev=>{ev.preventDefault();const data=new FormData(f);const b=f.querySelector('button')!;b.disabled=true;try{await api('/tasks','POST',{title:String(data.get('title')),due_on:data.get('due_on')||null,customer_id:f.dataset.taskCustomer?Number(f.dataset.taskCustomer):null});toast('Action enregistrée');if(clientOpen)await openClient(clientOpen);await load()}catch{toast('L’action n’a pas été enregistrée.')}finally{b.disabled=false}});const search=$<HTMLInputElement>('client-search');if(search)search.oninput=()=>{filter=search.value;const rows=overview.customers.filter(c=>(showInternal||!c.internal)&&[c.email,c.display_name,c.company,stages[c.stage]].join(' ').toLowerCase().includes(filter.toLowerCase()));$('client-results').innerHTML=clientTable(rows);document.querySelectorAll<HTMLButtonElement>('[data-client]').forEach(b=>b.onclick=()=>openClient(Number(b.dataset.client)))};const toggle=$<HTMLInputElement>('show-internal');if(toggle)toggle.onchange=()=>{showInternal=toggle.checked;render()};document.querySelectorAll<HTMLButtonElement>('[data-mail-filter]').forEach(b=>b.onclick=()=>{mailFilter=b.dataset.mailFilter!;$('view').innerHTML=renderMail();bind()});const ms=$<HTMLInputElement>('mail-search');if(ms)ms.oninput=()=>{const position=ms.selectionStart;filter=ms.value;$('view').innerHTML=renderMail();bind();const next=$<HTMLInputElement>('mail-search');next.focus();if(position!==null)next.setSelectionRange(position,position)};document.querySelectorAll<HTMLButtonElement>('[data-mail-id]').forEach(b=>b.onclick=()=>openMail(b.dataset.mailSource!,b.dataset.mailId!));document.querySelectorAll<HTMLButtonElement>('[data-disconnect-mail]').forEach(disconnect=>disconnect.onclick=async()=>{if(!confirm('Déconnecter cette boîte du CRM ? Aucun mail ne sera supprimé chez Infomaniak.'))return;try{await api('/mail/disconnect','POST',{user:disconnect.dataset.disconnectMail});toast('Boîte déconnectée. Révoquez aussi ce mot de passe d’appareil chez Infomaniak pour couper définitivement l’accès.');render()}catch{toast('Déconnexion impossible. Réessayez.')}});document.querySelectorAll<HTMLFormElement>('[data-mail-connect]').forEach(cf=>cf.onsubmit=async ev=>{ev.preventDefault();const d=new FormData(cf),b=cf.querySelector('button')!;b.disabled=true;try{await api('/mail/connect','POST',{user:d.get('user'),pass:d.get('pass'),personal_scope_ack:d.has('personal_scope_ack')});cf.reset();toast('Boîte connectée et accès vérifié');await render()}catch{toast('Connexion refusée. Vérifiez le mot de passe de la boîte.')}finally{b.disabled=false}});}

async function openClient(id:number){mailAbort?.abort();mailOpen++;clientOpen=id;$('detail-label').textContent='FICHE CLIENT';$('detail-body').innerHTML='<div class="loading-panel"><div class="spinner"></div>Ouverture de la fiche…</div>';const dialog=$<HTMLDialogElement>('detail');if(!dialog.open)dialog.showModal();try{const d=await api<Detail>('/customers/'+id);if(clientOpen!==id)return;const c=d.customer;$('detail-body').innerHTML=`<div class="detail-person"><div class="person-icon">${initials(clientName(c))}</div><div><h1>${e(clientName(c))}</h1><p class="fine">${e(c.email)}</p></div></div><div class="status-line">${pill(c.internal?'Compte interne':stages[c.stage]||'Nouveau',c.internal?'':'green')}<span class="fine">Depuis le ${date(c.created_at)}</span></div><section class="panel"><div class="panel-heading"><h2>La relation</h2><button class="button" id="client-mail">Voir les échanges ↗</button></div><form id="profile-form"><div class="form-grid"><label class="field">Nom du contact<input name="display_name" maxlength="120" value="${e(c.display_name)}" placeholder="À renseigner"/></label><label class="field">Entreprise<input name="company" maxlength="180" value="${e(c.company)}" placeholder="À confirmer avec le client"/></label><label class="field">État du suivi<select name="stage">${Object.entries(stages).map(([key,label])=>`<option value="${key}" ${key===c.stage?'selected':''}>${label}</option>`).join('')}</select></label><label class="toggle" style="align-self:end;padding:13px 0"><input name="internal" type="checkbox" ${c.internal?'checked':''}/> Compte interne / test</label></div><div class="form-actions"><button class="primary" type="submit">Enregistrer la fiche</button></div></form></section>${clientLanguagePanel(c)}<div class="grid-equal"><div class="kpi">${kpi('Achats payés',money(c.revenue_cents),'CHF',`${c.paid_orders} commande(s) en mode réel`).replace(/^<div class="kpi">|<\/div>$/g,'')}</div><div class="kpi"><div class="kpi-label">Dernière session conservée</div><div style="font-size:17px;margin-top:20px">${date(c.last_login_at,true)}</div><p class="kpi-foot">Une déconnexion peut supprimer cette trace.</p></div></div><section class="panel"><div class="panel-heading"><h2>Prochaines actions</h2></div>${actions(d.tasks.filter(t=>!t.done_at))}${taskForm(id)}</section><section class="panel"><div class="panel-heading"><h2>Notes de suivi</h2></div>${d.notes.length?d.notes.map(n=>`<div class="note"><p>${e(n.body)}</p><time>${date(n.created_at,true)}</time></div>`).join(''):'<p class="fine" style="margin-bottom:15px">Gardez ici les besoins exprimés et vos décisions.</p>'}<form id="note-form" class="note-form"><label class="field">Ajouter une note<textarea name="body" required maxlength="8000" placeholder="Un besoin exprimé, une information confirmée…"></textarea></label><div class="form-actions"><button class="button" type="submit">Ajouter la note</button></div></form></section><section class="panel"><div class="panel-heading"><h2>Achats et accès</h2></div>${d.orders.map(o=>`<div class="metric-row"><span>${date(o.created_at)} · ${e(orderItems(o.items_json))}<br/><small>${e(orderStatus(o.status,o.refunded_chf))}${o.dispute_status?` · ${e(disputeLabel(o.dispute_status))}`:''}${o.stripe_session_id.startsWith('cs_test_')?' · mode test':''}</small>${legalOrder(o)}</span><strong>${money(o.amount_chf)} CHF${o.refunded_chf?`<br/><small>Remboursé : ${money(o.refunded_chf)} CHF</small>`:''}${o.financial_checked_at?`<br/><small>Vérifié le ${date(o.financial_checked_at,true)}</small>`:''}${o.stripe_payment_intent?`<br/><a class="fine" href="https://dashboard.stripe.com/${o.stripe_session_id.startsWith('cs_test_')?'test/':''}payments/${encodeURIComponent(o.stripe_payment_intent)}" target="_blank" rel="noopener">Paiement ↗</a>`:''}</strong></div>${renderOrderService(o)}`).join('')||empty('Aucun achat')}<div style="margin-top:15px">${d.entitlements.map(t=>`<p class="fine"><strong>${e(t.dataset_id.toUpperCase())}</strong> · version ${e(t.current_version)}<br/>Mises à jour ${t.updates_until?'jusqu’au '+date(t.updates_until):'sans date de fin enregistrée'}</p>`).join('')}</div></section>${renderAccountDownloads(d.account_downloads)}`;bind();bindLanguageForm(c);$('client-mail').onclick=()=>{filter=c.email;mailFilter='all';dialog.close();clientOpen=null;if(location.hash==='#mail')render();else location.hash='mail'};$<HTMLFormElement>('profile-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget as HTMLFormElement,b=form.querySelector('button')!,f=new FormData(form);b.disabled=true;try{await api('/customers/'+id,'PATCH',{display_name:f.get('display_name'),company:f.get('company'),stage:f.get('stage'),internal:f.has('internal')});toast('Fiche enregistrée');await openClient(id);await load()}catch{toast('La fiche n’a pas été enregistrée.')}finally{b.disabled=false}};$<HTMLFormElement>('note-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget as HTMLFormElement,b=form.querySelector('button')!;b.disabled=true;try{await api('/customers/'+id+'/notes','POST',{body:new FormData(form).get('body')});toast('Note enregistrée');await openClient(id)}catch{toast('La note n’a pas été enregistrée.')}finally{b.disabled=false}};}catch{$('detail-body').innerHTML=empty('La fiche n’a pas pu être chargée')}}
function clientLanguagePanel(c:Client){
 const l=c.language;
 const origin=l.source==='manual'?'Préférence enregistrée dans le CRM':l.source==='checkout'?'Langue de la page d’achat · préférence à confirmer':'Aucune préférence confirmée. Nos propres envois ne permettent pas de la déduire.';
 return `<section class="panel"><div class="panel-heading"><h2>Langue de la relation</h2>${languagePill(l)}</div><p class="fine">${e(origin)}</p><form id="language-form"><label class="field">Langue à utiliser avec ce client<select name="code">${languageOptions(l.code)}</select></label><p class="fine">Choisissez une langue exprimée par le client ou vérifiée dans ses échanges. Une détection automatique reste une indication.</p><div class="form-actions"><button class="button" type="submit">Enregistrer la langue</button></div></form><p class="source-note">Mails automatiques actuels : ${e(languageName(l.transactional_code))}. Les modèles existent en français, anglais et allemand ; pour une autre langue, ils utilisent l’anglais. Vos réponses personnelles doivent suivre la langue choisie ci-dessus.</p></section>`;
}
function bindLanguageForm(c:Client){$<HTMLFormElement>('language-form').onsubmit=async event=>{
 event.preventDefault();const form=event.currentTarget as HTMLFormElement,button=form.querySelector('button')!;button.disabled=true;
 try{await api('/customers/'+c.id+'/language','PATCH',{code:new FormData(form).get('code')||null});toast('Langue enregistrée');await openClient(c.id);await load()}catch{toast('La langue n’a pas été enregistrée.')}finally{button.disabled=false}
};}
type MailDetail={subject:string;from:string;to:string[];created_at:string;status?:string;text:string;reading_text:string;language:Language;truncated?:boolean;attachments:{name:string;size:number}[]};
async function openMail(source:string,id:string){
 mailAbort?.abort();const current=++mailOpen;clientOpen=null;$('detail-label').textContent='MESSAGE';const dialog=$<HTMLDialogElement>('detail');if(!dialog.open)dialog.showModal();$('detail-body').innerHTML='<div class="loading-panel"><div class="spinner"></div>Ouverture du message…</div>';
 try{
  const m=await api<MailDetail>('/mail/'+encodeURIComponent(source)+'/'+encodeURIComponent(id));if(current!==mailOpen||!dialog.open)return;
  const sender=(m.from.match(/[A-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Z0-9.-]+/gi)||[]).map(x=>x.toLowerCase());
  const customer=overview.customers.find(c=>sender.includes(c.email.toLowerCase())&&!c.internal);
  const suggested=customer?.language.code||m.language.code;
  $('detail-body').innerHTML=`<h1>${e(m.subject)}</h1><p class="fine">De : ${e(m.from)}<br/>À : ${e(m.to.join(', '))}<br/>${date(m.created_at,true)}</p><div class="status-line">${languagePill(m.language)}${m.language.code?`<span class="fine">${m.language.source==='template'?'Langue déclarée dans le mail':'Détection automatique · à vérifier'}</span>`:''}${m.status?pill(states[m.status]||m.status,'green'):''}</div>${customer?`<div class="notice">Réponse conseillée : <strong>${e(languageName(suggested))}</strong> · ${customer.language.code?'selon la fiche client':'selon ce message, à confirmer'}. <button class="text-button" id="mail-client">Ouvrir sa fiche</button></div>`:''}<section class="panel"><div class="mail-reading-head"><div class="tabs" role="group" aria-label="Langue de lecture"><button id="read-original" class="active" aria-pressed="true">Original</button><button id="read-french" aria-pressed="false">Français</button></div><label class="field">Langue du message<select id="message-language">${languageOptions(m.language.code)}</select></label></div><p id="translation-status" class="fine" role="status">${m.language.code==='fr'?'Le texte courant est détecté en français.':'La traduction française est une aide à la lecture ; l’original reste la référence.'}</p>${m.reading_text&&m.reading_text!==m.text?'<div class="translation-scope"><p class="fine">La traduction porte sur le nouveau texte. Les citations et messages transférés restent dans l’original.</p><label class="toggle"><input id="include-history" type="checkbox"/> Traduire aussi les citations et transferts</label></div>':''}<pre class="mail-body" id="mail-original">${e(m.text)}</pre><div id="translation-pane" hidden><p class="translation-label">TRADUCTION AUTOMATIQUE · FRANÇAIS</p><pre class="mail-body" id="mail-french"></pre><button class="button" id="translate-more" hidden>Traduire la suite</button></div></section>${m.truncated?'<p class="notice">Message volumineux : aperçu partiel. Ouvrez Infomaniak pour le message complet.</p>':''}${m.attachments.length?`<section class="panel"><h2>Pièces jointes</h2>${m.attachments.map(a=>`<div class="metric-row"><span>${e(a.name)}</span><strong>${Math.ceil(a.size/1024)} Ko</strong></div>`).join('')}<p class="fine">Disponibles dans votre messagerie Infomaniak.</p></section>`:''}<a class="button" href="https://ksuite.infomaniak.com/mail" target="_blank" rel="noopener">Ouvrir la messagerie pour répondre ↗</a>`;
  if(customer)$('mail-client').onclick=()=>openClient(customer.id);
  bindTranslation(m,current);
 }catch{if(current===mailOpen)$('detail-body').innerHTML=empty('Ce message n’est pas disponible','Réessayez ou ouvrez votre messagerie.')}
}
function bindTranslation(m:MailDetail,current:number){
 const original=$('mail-original'),pane=$('translation-pane'),output=$('mail-french'),status=$('translation-status'),more=$<HTMLButtonElement>('translate-more'),select=$<HTMLSelectElement>('message-language');
 let offset=0,running=false,complete=false;
 const show=(french:boolean)=>{original.hidden=french;pane.hidden=!french;for(const [id,active] of [['read-original',!french],['read-french',french]] as const){$(id).classList.toggle('active',active);$(id).setAttribute('aria-pressed',String(active))}};
 async function translate(){
  if(running||complete)return;const lang=select.value;
  if(!lang){status.textContent='Choisissez la langue du message pour lancer la traduction.';select.focus();return}
  show(true);pane.querySelector('.translation-label')!.textContent='TRADUCTION AUTOMATIQUE · FRANÇAIS';
  if(lang==='fr'){pane.querySelector('.translation-label')!.textContent='TEXTE ORIGINAL · FRANÇAIS';output.textContent=m.text;status.textContent='Texte original : ce message est en français.';complete=true;return}
  const includeHistory=$<HTMLInputElement>('include-history')?.checked;
  const text=includeHistory?m.text:m.reading_text||m.text;
  // Un lot reste sous la limite serveur, y compris avec les caractères Unicode.
  let end=Math.min(text.length,offset+3500);while(new TextEncoder().encode(text.slice(offset,end)).length>12000)end--;
  if(end<text.length){const sentences=[...new Intl.Segmenter(lang,{granularity:'sentence'}).segment(text.slice(offset,end))];const prior=sentences.length>1?sentences.at(-1)!.index:0;if(prior>100)end=offset+prior;else{const space=text.lastIndexOf(' ',end);if(space>offset+1000)end=space}}
  const part=text.slice(offset,end);if(!part.trim()){complete=true;return}
  const before=output.textContent||'';running=true;more.hidden=true;select.disabled=true;if($<HTMLInputElement>('include-history'))$<HTMLInputElement>('include-history').disabled=true;mailAbort=new AbortController();
  status.textContent='Traduction en cours sur le serveur OpenSwissData… Le texte apparaît au fur et à mesure.';
  try{
   const response=await fetch('/api/admin/crm/mail/translate',{method:'POST',credentials:'same-origin',cache:'no-store',signal:mailAbort.signal,headers:{'Content-Type':'application/json','x-osd-csrf':'dashboard'},body:JSON.stringify({language:lang,text:part})});
   if(!response.ok){if([401,403].includes(response.status)){await api('/overview');return}throw new Error(response.status===429?'busy':'failed')}
   if(!response.body)throw new Error('failed');const reader=response.body.getReader(),decoder=new TextDecoder();let pending='',done=false;
   while(true){const item=await reader.read();if(item.done)break;pending+=decoder.decode(item.value,{stream:true});const lines=pending.split('\n');pending=lines.pop()!;for(const line of lines){if(!line)continue;const event=JSON.parse(line);if(current!==mailOpen)return;if(event.type==='error')throw new Error(event.error);if(event.type==='done')done=true;if(event.type==='chunk'){output.textContent+=event.text;status.textContent=`Traduction en cours : ${event.completed} / ${event.total} passages.`}}}
   if(!done)throw new Error('failed');offset=end;complete=offset>=text.length;
   status.textContent=complete?`Traduction automatique terminée.${!includeHistory&&m.reading_text&&m.reading_text!==m.text?' Citations et transferts non traduits : cochez l’option pour les inclure.':''} Vérifiez l’original avant une décision ou une réponse.`:'Traduction partielle. Continuez avec « Traduire la suite » pour lire le reste.';
   more.textContent='Traduire la suite';more.hidden=complete;
  }catch(error){if(current!==mailOpen)return;if(error instanceof DOMException&&error.name==='AbortError')return;output.textContent=before;status.textContent=error instanceof Error&&['busy','translation_busy'].includes(error.message)?'Une autre traduction est en cours. Réessayez dans un instant.':'Traduction interrompue. L’original est disponible ; vous pouvez réessayer.';more.textContent='Réessayer la traduction';more.hidden=false}
  finally{running=false;select.disabled=false;if($<HTMLInputElement>('include-history'))$<HTMLInputElement>('include-history').disabled=false}
 }
 $('read-original').onclick=()=>show(false);$('read-french').onclick=()=>{show(true);translate()};more.onclick=translate;
 const reset=()=>{mailAbort?.abort();output.textContent='';offset=0;complete=false;more.hidden=true;status.textContent='Langue du message modifiée. Ouvrez « Français » pour traduire.';show(false)};select.onchange=reset;const history=$<HTMLInputElement>('include-history');if(history)history.onchange=reset;
 if(m.language.code&&m.language.code!=='fr')translate();
}
window.addEventListener('hashchange',()=>{active=sectionInfo[location.hash.slice(1)]?location.hash.slice(1):'overview';if(active!=='mail')filter='';render()});$('close-detail').onclick=()=>$<HTMLDialogElement>('detail').close();$('detail').addEventListener('close',()=>{clientOpen=null;mailOpen++;mailAbort?.abort();$('detail-body').textContent=''});$('refresh').onclick=load;$<HTMLSelectElement>('period').onchange=load;$('today').textContent=new Intl.DateTimeFormat('fr-CH',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Zurich'}).format(new Date());const logout=async()=>{await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin'});location.assign('/admin')};$('logout').onclick=logout;$('logout-top').onclick=logout;$<HTMLFormElement>('login-form').onsubmit=async ev=>{ev.preventDefault();const form=ev.currentTarget as HTMLFormElement,b=form.querySelector('button')!;b.disabled=true;try{const response=await fetch('/api/auth/magic-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:new FormData(form).get('email'),return_to:'admin'})});$('gate-status').textContent=response.ok?'Si cette adresse possède un compte, un lien vient de lui être envoyé. Ouvrez-le pour accéder directement au bureau.':'Veuillez patienter quelques secondes avant de réessayer.';}catch{$('gate-status').textContent='Envoi impossible pour le moment. Réessayez.'}finally{b.disabled=false}};
load();
